insert into toeic_tests (language_id, title, questions, exam_type)
select lang.id, 'IELTS-like — Test 1', '{"duration_minutes": 45, "part_a": [{"question": "Complète : My neighbor ___ moved to Australia last month.", "options": ["has", "have", "had", "was"], "correct_index": 0}, {"question": "Complète : If I ___ more free time, I would travel more.", "options": ["have", "had", "will have", "has"], "correct_index": 1}, {"question": "Complète : The council ___ improve public transport next year.", "options": ["plans to", "plan to", "planning to", "plans"], "correct_index": 0}, {"question": "Complète : She''s been living here ___ ten years.", "options": ["since", "for", "from", "during"], "correct_index": 1}, {"question": "Complète : This is the shop ___ I bought my bike.", "options": ["who", "where", "which", "whose"], "correct_index": 1}, {"question": "Complète : Despite ___ hard, he failed the interview.", "options": ["try", "trying", "tried", "to try"], "correct_index": 1}, {"question": "Complète : The new policy ___ by the local council last week.", "options": ["announced", "was announced", "announces", "is announce"], "correct_index": 1}, {"question": "Complète : I wish I ___ how to swim.", "options": ["know", "knew", "known", "will know"], "correct_index": 1}, {"question": "Complète : Not only ___ late, but he also forgot his passport.", "options": ["he was", "was he", "did he", "he did"], "correct_index": 1}, {"question": "Complète : ___ the traffic, we arrived on time.", "options": ["Although", "Because", "Despite", "So"], "correct_index": 2}, {"question": "Complète : The results ___ next week.", "options": ["will announce", "will be announced", "announces", "is announce"], "correct_index": 1}, {"question": "Complète : She''s the woman ___ car was stolen.", "options": ["who", "whose", "which", "that"], "correct_index": 1}, {"question": "Complète : We should ___ leave now to catch the train.", "options": ["better", "had better", "have better", "best"], "correct_index": 1}, {"question": "Complète : He denied ___ the window.", "options": ["break", "breaking", "to break", "broke"], "correct_index": 1}, {"question": "Complète : The community centre ___ renovated last year.", "options": ["was", "were", "is", "has"], "correct_index": 0}, {"question": "Complète : ___ you finished the report yet?", "options": ["Do", "Did", "Have", "Are"], "correct_index": 2}, {"question": "Complète : This café is ___ than the one downtown.", "options": ["quiet", "quieter", "quietest", "more quiet"], "correct_index": 1}, {"question": "Complète : I''d rather you ___ here tonight.", "options": ["stay", "stayed", "to stay", "staying"], "correct_index": 1}, {"question": "Complète : The volunteers ___ hundreds of hours to the project.", "options": ["contribute", "contributed", "have contributed", "contributing"], "correct_index": 2}, {"question": "Complète : It''s the local market ___ attracts most tourists.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : He''s used to ___ early for work.", "options": ["wake", "waking", "woke", "to wake"], "correct_index": 1}, {"question": "Complète : The event has been ___ due to bad weather.", "options": ["cancelled", "cancel", "cancelling", "cancels"], "correct_index": 0}, {"question": "Complète : Neither of the applicants ___ suitable.", "options": ["are", "is", "were", "have been"], "correct_index": 1}, {"question": "Complète : She must ___ forgotten about the meeting.", "options": ["has", "have", "had", "having"], "correct_index": 1}, {"question": "Complète : The population ___ significantly over the past decade.", "options": ["grew", "has grown", "grow", "growing"], "correct_index": 1}, {"question": "Complète : ___ working overtime, she still met the deadline.", "options": ["Despite", "Although", "Because", "So"], "correct_index": 0}, {"question": "Complète : The council recommended that residents ___ their bins earlier.", "options": ["puts", "put", "putting", "to put"], "correct_index": 1}, {"question": "Complète : This is the second time she ___ late this week.", "options": ["is", "was", "has been", "had been"], "correct_index": 2}, {"question": "Complète : The negotiations fell ___ at the last minute.", "options": ["through", "out", "up", "down"], "correct_index": 0}, {"question": "Complète : What surprised residents most ___ the sudden price increase.", "options": ["was", "were", "have been", "being"], "correct_index": 0}], "part_b": [{"title": "Annonce communautaire", "passage": "The local council is inviting residents to a public meeting next Thursday to discuss plans for a new community garden. The meeting will take place at the town hall at 6:30pm. Light refreshments will be provided, and residents are encouraged to share their ideas and concerns.", "questions": [{"question": "What is being discussed at the meeting?", "options": ["A new road", "A community garden", "A school closure", "A tax increase"], "correct_index": 1}, {"question": "When is the meeting?", "options": ["This Thursday", "Next Thursday", "Next Monday", "Not specified"], "correct_index": 1}, {"question": "Where will it take place?", "options": ["A community garden", "The town hall", "A local school", "A park"], "correct_index": 1}, {"question": "What time does the meeting start?", "options": ["5:30pm", "6:30pm", "7:30pm", "8:00pm"], "correct_index": 1}, {"question": "What will be provided at the meeting?", "options": ["Full dinner", "Light refreshments", "Nothing", "Transportation"], "correct_index": 1}, {"question": "What are residents encouraged to do?", "options": ["Stay silent", "Share ideas and concerns", "Vote immediately", "Sign a petition"], "correct_index": 1}]}, {"title": "Article général (santé)", "passage": "Regular physical activity has been shown to reduce the risk of several chronic illnesses, including heart disease and diabetes. Health experts recommend at least 150 minutes of moderate exercise per week, though many adults struggle to meet this target due to busy schedules.", "questions": [{"question": "What does regular physical activity reduce?", "options": ["The risk of chronic illnesses", "Sleep quality", "Appetite", "Social interaction"], "correct_index": 0}, {"question": "What illnesses are mentioned?", "options": ["Colds and flu", "Heart disease and diabetes", "Allergies", "Headaches"], "correct_index": 1}, {"question": "How much exercise do experts recommend weekly?", "options": ["50 minutes", "100 minutes", "150 minutes", "300 minutes"], "correct_index": 2}, {"question": "What kind of exercise is recommended?", "options": ["Intense only", "Moderate", "None specified", "Only running"], "correct_index": 1}, {"question": "Why do many adults struggle to meet this target?", "options": ["Lack of interest", "Busy schedules", "Health restrictions", "Cost of gyms"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["Diet advice", "The benefits and challenges of exercise", "A gym advertisement", "A medical treatment"], "correct_index": 1}]}, {"title": "Avis client (transport)", "passage": "I used this taxi service for my airport transfer last week. The driver arrived exactly on time and the car was clean and comfortable. Booking through the app was straightforward, though the price was slightly higher than I expected. Overall, I would use this service again.", "questions": [{"question": "What was the service used for?", "options": ["A city tour", "An airport transfer", "A long road trip", "A delivery service"], "correct_index": 1}, {"question": "Was the driver on time?", "options": ["No, very late", "Yes, exactly on time", "A bit early", "Not mentioned"], "correct_index": 1}, {"question": "How was the car described?", "options": ["Dirty and uncomfortable", "Clean and comfortable", "Too small", "Not mentioned"], "correct_index": 1}, {"question": "How was the booking process?", "options": ["Complicated", "Straightforward", "Impossible", "Required a phone call"], "correct_index": 1}, {"question": "What was slightly disappointing?", "options": ["The driver''s attitude", "The price", "The car''s cleanliness", "The punctuality"], "correct_index": 1}, {"question": "Would the reviewer use the service again?", "options": ["No, never", "Yes", "Undecided", "Not mentioned"], "correct_index": 1}]}, {"title": "Email (organisation d''événement)", "passage": "Dear volunteers, Thank you for signing up to help at Saturday''s charity fun run. Please arrive at the park by 7:30am to collect your volunteer t-shirt and instructions. The event starts at 9am and should finish by midday. Refreshments will be provided for all volunteers.", "questions": [{"question": "What event is being organized?", "options": ["A concert", "A charity fun run", "A conference", "A food festival"], "correct_index": 1}, {"question": "What time should volunteers arrive?", "options": ["7:00am", "7:30am", "8:30am", "9:00am"], "correct_index": 1}, {"question": "What will volunteers receive on arrival?", "options": ["Payment", "A t-shirt and instructions", "A meal voucher", "A certificate"], "correct_index": 1}, {"question": "What time does the event start?", "options": ["7:30am", "8am", "9am", "10am"], "correct_index": 2}, {"question": "When should the event finish?", "options": ["11am", "Midday", "2pm", "Evening"], "correct_index": 1}, {"question": "What is provided for volunteers?", "options": ["Nothing extra", "Refreshments", "Transportation only", "A gift bag"], "correct_index": 1}]}, {"title": "Article général (environnement)", "passage": "Many households are switching to reusable shopping bags to reduce plastic waste. While this shift has led to a noticeable decrease in single-use plastic bags, some experts point out that reusable bags require more resources to produce and must be used many times to have a positive environmental impact.", "questions": [{"question": "What are many households switching to?", "options": ["Paper bags only", "Reusable shopping bags", "No bags at all", "Plastic containers"], "correct_index": 1}, {"question": "What has this shift led to?", "options": ["An increase in plastic bags", "A decrease in single-use plastic bags", "No change", "Higher grocery prices"], "correct_index": 1}, {"question": "What do some experts point out?", "options": ["Reusable bags are perfect", "They require more resources to produce", "They are cheaper to make", "They are illegal in some areas"], "correct_index": 1}, {"question": "What is needed for reusable bags to have a positive impact?", "options": ["A single use", "Many uses", "Government approval", "A special license"], "correct_index": 1}, {"question": "What is the overall tone of the passage?", "options": ["Purely positive", "Balanced, noting pros and cons", "Purely negative", "Sarcastic"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["Fashion trends", "The environmental impact of reusable bags", "Grocery store pricing", "A new law"], "correct_index": 1}]}]}'::jsonb, 'ielts'
